G=load()

def transform(g):
    h,w=len(g),len(g[0])
    # find border rectangle of 3s
    threes=[(i,j) for i in range(h) for j in range(w) if g[i][j]==3]
    r0=min(i for i,j in threes); r1=max(i for i,j in threes)
    c0=min(j for i,j in threes); c1=max(j for i,j in threes)
    border={(i,j) for i,j in threes if i in(r0,r1) or j in(c0,c1)}
    markers=[(i,j) for i,j in threes if (i,j) not in border]
    out=[row[:] for row in g]
    for i in range(r0+1,r1):
        for j in range(c0+1,c1):
            if (i,j) in markers: continue
            d=min(max(abs(i-mi),abs(j-mj)) for mi,mj in markers)
            out[i][j]= 4 if d%2==1 else 2
    return out

